import type { CSSProperties } from "react";
import type { ChatPhase } from "../../types/chat";
import "../../styles/moonie.css";

export type MoonieSheet = {
  src: string;
  frameWidth: number;
  frameHeight: number;
  frameCount: number;
  scale: number;
  duration: string;
};

export const MOONIE_SHEETS = {
  face: {
    src: "/lunita_face.png",
    frameWidth: 128,
    frameHeight: 123,
    frameCount: 8,
    scale: 0.4,
    duration: "1.3s",
  },
  // Generated by scripts/normalize-moonie-sheet.ps1 — the raw export cuts the frames.
  playing: {
    src: "/lunita_playing_frames.png",
    frameWidth: 133,
    frameHeight: 116,
    frameCount: 8,
    scale: 0.5,
    duration: "1.3s",
  },
} satisfies Record<string, MoonieSheet>;

export type MoonieVariant = keyof typeof MOONIE_SHEETS;

export type MooniePhase = ChatPhase;

// streaming and done are placeholders until the barking and closing sprites exist.
export const MOONIE_PHASES: Record<
  MooniePhase,
  { variant: MoonieVariant; scale?: number; smooth?: boolean }
> = {
  thinking: { variant: "playing" },
  streaming: { variant: "face", scale: 0.22, smooth: true },
  done: { variant: "face", scale: 0.22, smooth: true },
};

type MoonieSpriteProps = {
  variant: MoonieVariant;
  scale?: number;
  duration?: string;
  smooth?: boolean;
  className?: string;
};

export default function MoonieSprite({
  variant,
  scale,
  duration,
  smooth,
  className,
}: MoonieSpriteProps) {
  const sheet = MOONIE_SHEETS[variant];

  const style = {
    "--sprite-image": `url("${sheet.src}")`,
    "--frame-width": `${sheet.frameWidth}px`,
    "--frame-height": `${sheet.frameHeight}px`,
    "--frame-count": sheet.frameCount,
    "--sprite-scale": scale ?? sheet.scale,
    "--sprite-duration": duration ?? sheet.duration,
    ...(smooth ? { imageRendering: "auto" } : {}),
  } as CSSProperties;

  return (
    <span
      className={["moonie-sprite", `moonie-sprite--${variant}`, className].filter(Boolean).join(" ")}
      style={style}
      aria-hidden="true"
    />
  );
}
